/**
 * build-terrain-tiles.mjs — streamed terrain for v3 (plan 10 S4, format from
 * _templates/spikes/RESULTS.md): a 3D Tiles 1.1 quadtree of the Copernicus GLO-30
 * surface model of Muir Inlet with the Sentinel-2 10 m true-colour image inside
 * each tile.
 *
 * Inputs (both gitignored, regenerated by scripts):
 *   data/work/dem-l0-f32.tif   30 m DEM, UTM 8N (npm run data:dem)
 *   data/raw/sentinel2/S2B_8VML_20240806_0_L2A-muir-10m.tif   (scripts/fetch-sentinel2-10m.sh)
 * Output: public/tiles/muir/tileset.json, public/tiles/muir/<L>/<x>_<y>.glb,
 *         public/tiles/muir/build-meta.json
 *
 * Layout: one root over the whole DEM footprint (32.4 x 44.04 km), split 2 x 2 per
 * level, L0..L4. Each tile is a 68 x 92 cell grid (the footprint's aspect), so the
 * L4 leaves sample about 30 m, the DEM's own spacing: no detail is invented below
 * the data. One skirt ring per tile hides LOD cracks. geometricError = measured
 * max vertical error of the tile against the 30 m DEM (0 at the leaves).
 * Imagery per tile: L4 10 m/px (the Sentinel-2 native resolution), L3 20 m, L2 40 m,
 * L1 80 m, L0 160 m; box-averaged, JPEG q84, no colour retouching.
 *
 * Frame (matches src/systems/terrain-data.js): 1 unit = 1 m, no vertical
 * exaggeration. GLB is Y-up with x = east - centreE, y = elevation (DEM datum),
 * z = centreN - north (south). tileset.json is Z-up (gltfUpAxis Y): x east,
 * y north, z up, same origin. In three.js, set tiles.group.rotation.x = -Math.PI / 2
 * and the tiles land in the scene frame used by the v2 heightfield.
 * UV (TEXCOORD_0): (0,0) at the tile's north-west corner, v increases southward
 * (glTF image convention, GLTFLoader flipY = false).
 * GLB compression: KHR_mesh_quantization + EXT_meshopt_compression (decoder in
 * the template's core/assets.js).
 */
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { Document, Logger, NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import { meshopt } from '@gltf-transform/functions';
import { MeshoptEncoder } from 'meshoptimizer';
import { assertLicence } from './lib/licence.mjs';

const DEM = 'data/work/dem-l0-f32.tif';
const S2 = 'data/raw/sentinel2/S2B_8VML_20240806_0_L2A-muir-10m.tif';
const OUT = 'public/tiles/muir';
const TMP = 'tmp/tiles';
const LEVELS = 5;
const CX = 68;
const CY = 92;
const S2_RES = 10;

for (const [f, how] of [[DEM, 'npm run data:dem'], [S2, 'bash scripts/fetch-sentinel2-10m.sh']]) {
  if (!existsSync(f)) { console.error(`missing ${f}: run ${how}`); process.exit(1); }
}
assertLicence('copernicus-glo30', 'Copernicus DEM licence');
assertLicence('sentinel-2-l2a', 'Copernicus Sentinel data licence (Sentinel_Data_Legal_Notice)');

mkdirSync(TMP, { recursive: true });
rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });

const gdalJson = (f) => JSON.parse(execFileSync('gdalinfo', ['-json', f], { maxBuffer: 1 << 26 }).toString());
const demInfo = gdalJson(DEM);
const [W, H] = demInfo.size;
const [WEST, DX, , NORTH, , DYN] = demInfo.geoTransform;
const RES = DX;
if (RES !== 30 || DYN !== -30) throw new Error(`expected a 30 m DEM, got ${DX} x ${DYN}`);
const EAST = WEST + W * RES;
const SOUTH = NORTH - H * RES;
const centreE = (WEST + EAST) / 2;
const centreN = (NORTH + SOUTH) / 2;
const demRaw = join(TMP, 'dem.f32');
execFileSync('gdal_translate', ['-q', '-of', 'ENVI', '-ot', 'Float32', DEM, demRaw]);
const dem = new Float32Array(readFileSync(demRaw).buffer.slice(0));

const s2Info = gdalJson(S2);
const [SW, SH] = s2Info.size;
const [S2W, , , S2N] = s2Info.geoTransform;
if (S2W !== WEST || S2N !== NORTH || SW * S2_RES !== W * RES || SH * S2_RES !== H * RES) {
  throw new Error('Sentinel-2 window does not match the DEM footprint');
}
const s2Raw = join(TMP, 's2.rgb');
execFileSync('gdal_translate', ['-q', '-of', 'ENVI', '-co', 'INTERLEAVE=BIP', S2, s2Raw]);
const s2 = new Uint8Array(readFileSync(s2Raw).buffer.slice(0));
let nodata = 0;
for (let i = 0; i < SW * SH; i++) if (s2[i * 3] === 0 && s2[i * 3 + 1] === 0 && s2[i * 3 + 2] === 0) nodata++;
console.log({ W, H, SW, SH, nodataPct: +(100 * nodata / (SW * SH)).toFixed(3) });

// Bilinear DEM sample at metres (e, n); pixel centres at west + (i + 0.5) * RES.
function elev(e, n) {
  const gx = Math.min(W - 1, Math.max(0, (e - WEST) / RES - 0.5));
  const gy = Math.min(H - 1, Math.max(0, (NORTH - n) / RES - 0.5));
  const i = Math.min(W - 2, Math.floor(gx)), j = Math.min(H - 2, Math.floor(gy));
  const a = gx - i, b = gy - j;
  const p = j * W + i;
  return (dem[p] * (1 - a) + dem[p + 1] * a) * (1 - b) + (dem[p + W] * (1 - a) + dem[p + W + 1] * a) * b;
}

// Box-averaged imagery for a tile: `px` x `py` output pixels over [e0,e1] x [n1,n0].
function tileImage(e0, n0, spanE, spanN, px, py) {
  const out = Buffer.alloc(px * py * 3);
  const sx = spanE / px / S2_RES, sy = spanN / py / S2_RES; // source px per output px
  const c0 = (e0 - WEST) / S2_RES, r0 = (NORTH - n0) / S2_RES;
  for (let y = 0; y < py; y++) {
    const ra = Math.floor(r0 + y * sy), rb = Math.max(ra + 1, Math.floor(r0 + (y + 1) * sy));
    for (let x = 0; x < px; x++) {
      const ca = Math.floor(c0 + x * sx), cb = Math.max(ca + 1, Math.floor(c0 + (x + 1) * sx));
      let r = 0, g = 0, b = 0, k = 0;
      for (let rr = ra; rr < rb; rr++) for (let cc = ca; cc < cb; cc++) {
        const q = (Math.min(SH - 1, rr) * SW + Math.min(SW - 1, cc)) * 3;
        if (s2[q] === 0 && s2[q + 1] === 0 && s2[q + 2] === 0) continue;
        r += s2[q]; g += s2[q + 1]; b += s2[q + 2]; k++;
      }
      const o = (y * px + x) * 3;
      if (k) { out[o] = r / k; out[o + 1] = g / k; out[o + 2] = b / k; }
    }
  }
  return execFileSync('magick', ['-size', `${px}x${py}`, '-depth', '8', 'rgb:-', '-strip', '-quality', '84', '-sampling-factor', '4:2:0', 'jpg:-'], { input: out, maxBuffer: 1 << 26 });
}

const io = new NodeIO().registerExtensions(ALL_EXTENSIONS).registerDependencies({ 'meshopt.encoder': MeshoptEncoder });
await MeshoptEncoder.ready;

let tileCount = 0, glbBytes = 0, largest = 0, maxTris = 0;
async function buildTile(level, tx, ty) {
  const spanE = (EAST - WEST) / 2 ** level, spanN = (NORTH - SOUTH) / 2 ** level;
  const e0 = WEST + tx * spanE, n0 = NORTH - ty * spanN; // north-west corner
  const nx = CX + 1, ny = CY + 1;
  const de = spanE / CX, dn = spanN / CY;
  const hs = new Float32Array(nx * ny);
  let zmin = Infinity, zmax = -Infinity;
  for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
    const h = elev(e0 + i * de, n0 - j * dn);
    hs[j * nx + i] = h; if (h < zmin) zmin = h; if (h > zmax) zmax = h;
  }
  // Max vertical error of this tile's bilinear surface vs the DEM pixel centres inside it.
  let err = 0;
  if (level < LEVELS - 1) {
    const i0 = Math.floor((e0 - WEST) / RES), i1 = Math.ceil((e0 + spanE - WEST) / RES);
    const j0 = Math.floor((NORTH - n0) / RES), j1 = Math.ceil((NORTH - (n0 - spanN)) / RES);
    for (let pj = j0; pj < Math.min(H, j1); pj++) for (let pi = i0; pi < Math.min(W, i1); pi++) {
      const e = WEST + (pi + 0.5) * RES, n = NORTH - (pj + 0.5) * RES;
      const fi = Math.min(CX - 1e-6, Math.max(0, (e - e0) / de)), fj = Math.min(CY - 1e-6, Math.max(0, (n0 - n) / dn));
      const i = Math.floor(fi), j = Math.floor(fj), a = fi - i, b = fj - j;
      const hb = (hs[j * nx + i] * (1 - a) + hs[j * nx + i + 1] * a) * (1 - b) + (hs[(j + 1) * nx + i] * (1 - a) + hs[(j + 1) * nx + i + 1] * a) * b;
      const d = Math.abs(dem[pj * W + pi] - hb);
      if (d > err) err = d;
    }
  }
  const skirt = Math.max(10, err * 2 + Math.max(de, dn));
  const pos = [], nrm = [], uv = [];
  const g = RES; // normals from the full-resolution DEM
  for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
    const e = e0 + i * de, n = n0 - j * dn;
    const dhde = (elev(e + g, n) - elev(e - g, n)) / (2 * g);
    const dhdn = (elev(e, n + g) - elev(e, n - g)) / (2 * g);
    const len = Math.hypot(dhde, dhdn, 1);
    pos.push(e - centreE, hs[j * nx + i], centreN - n);
    nrm.push(-dhde / len, 1 / len, dhdn / len); // (east, up, south)
    uv.push(i / CX, j / CY);
  }
  const idx = [];
  for (let j = 0; j < CY; j++) for (let i = 0; i < CX; i++) {
    const a = j * nx + i, b = a + 1, c = a + nx, d = c + 1;
    idx.push(a, c, b, b, c, d);
  }
  const border = [];
  for (let i = 0; i < nx; i++) border.push(i);
  for (let j = 1; j < ny; j++) border.push(j * nx + nx - 1);
  for (let i = nx - 2; i >= 0; i--) border.push((ny - 1) * nx + i);
  for (let j = ny - 2; j > 0; j--) border.push(j * nx);
  const base = pos.length / 3;
  for (const k of border) {
    pos.push(pos[k * 3], pos[k * 3 + 1] - skirt, pos[k * 3 + 2]);
    nrm.push(nrm[k * 3], nrm[k * 3 + 1], nrm[k * 3 + 2]);
    uv.push(uv[k * 2], uv[k * 2 + 1]);
  }
  for (let s = 0; s < border.length; s++) {
    const a = border[s], b = border[(s + 1) % border.length];
    const a2 = base + s, b2 = base + ((s + 1) % border.length);
    idx.push(a, b, a2, b, b2, a2, a, a2, b, b, a2, b2);
  }
  maxTris = Math.max(maxTris, idx.length / 3);

  const resM = S2_RES * 2 ** (LEVELS - 1 - level);
  const px = Math.round(spanE / resM), py = Math.round(spanN / resM);
  const jpg = tileImage(e0, n0, spanE, spanN, px, py);

  const doc = new Document().setLogger(new Logger(Logger.Verbosity.WARN));
  const buffer = doc.createBuffer();
  const tex = doc.createTexture(`s2-L${level}`).setImage(new Uint8Array(jpg)).setMimeType('image/jpeg');
  const mat = doc.createMaterial('terrain-s2-2024').setBaseColorTexture(tex).setRoughnessFactor(0.95).setMetallicFactor(0);
  const prim = doc.createPrimitive()
    .setAttribute('POSITION', doc.createAccessor().setType('VEC3').setArray(new Float32Array(pos)).setBuffer(buffer))
    .setAttribute('NORMAL', doc.createAccessor().setType('VEC3').setArray(new Float32Array(nrm)).setBuffer(buffer))
    .setAttribute('TEXCOORD_0', doc.createAccessor().setType('VEC2').setArray(new Float32Array(uv)).setBuffer(buffer))
    .setIndices(doc.createAccessor().setType('SCALAR').setArray(new Uint16Array(idx)).setBuffer(buffer))
    .setMaterial(mat);
  const mesh = doc.createMesh(`L${level}_${tx}_${ty}`).addPrimitive(prim);
  doc.createScene().addChild(doc.createNode('tile').setMesh(mesh).setExtras({ level, tx, ty, imageryMPerPx: resM }));
  await doc.transform(meshopt({ encoder: MeshoptEncoder, level: 'high', quantizeNormal: 8, quantizeTexcoord: 12 }));
  const glb = await io.writeBinary(doc);
  const rel = `${level}/${tx}_${ty}.glb`;
  mkdirSync(join(OUT, String(level)), { recursive: true });
  writeFileSync(join(OUT, rel), glb);
  tileCount++; glbBytes += glb.length; largest = Math.max(largest, glb.length);
  if (tileCount % 50 === 0) console.log('tiles', tileCount);

  // Z-up tileset frame: x east, y north, z up (origin = DEM grid centre).
  const xa = e0 - centreE, xb = e0 + spanE - centreE;
  const ya = n0 - spanN - centreN, yb = n0 - centreN;
  const zlo = zmin - skirt, zhi = zmax;
  const tile = {
    boundingVolume: { box: [(xa + xb) / 2, (ya + yb) / 2, (zlo + zhi) / 2, (xb - xa) / 2, 0, 0, 0, (yb - ya) / 2, 0, 0, 0, (zhi - zlo) / 2 + 0.5] },
    geometricError: level === LEVELS - 1 ? 0 : Math.max(0.5, +err.toFixed(2)),
    refine: 'REPLACE',
    content: { uri: rel },
  };
  if (level < LEVELS - 1) {
    tile.children = [];
    for (let cy = 0; cy < 2; cy++) for (let cx = 0; cx < 2; cx++) tile.children.push(await buildTile(level + 1, tx * 2 + cx, ty * 2 + cy));
    let lo = Infinity, hi = -Infinity;
    for (const c of [tile, ...tile.children]) { const b = c.boundingVolume.box; lo = Math.min(lo, b[2] - b[11]); hi = Math.max(hi, b[2] + b[11]); }
    tile.boundingVolume.box[2] = (lo + hi) / 2; tile.boundingVolume.box[11] = (hi - lo) / 2;
  }
  return tile;
}

const t0 = Date.now();
const root = await buildTile(0, 0, 0);
const tileset = {
  // Only 1.0 features are used (GLB content, box volumes); "1.0" avoids the
  // 3d-tiles-renderer 0.5.3 "limited support for 1.1" warning (RESULTS.md finding 7).
  asset: {
    version: '1.0',
    gltfUpAxis: 'Y',
    generator: 'glacier-time-machine scripts/build-terrain-tiles.mjs',
    extras: {
      attribution: 'produced using Copernicus WorldDEM-30 © DLR e.V. 2010-2014 and © Airbus Defence and Space GmbH 2014-2018 provided under COPERNICUS by the European Union and ESA; all rights reserved. Contains modified Copernicus Sentinel data 2024.',
      frame: 'Z-up: x east, y north, z up (m); origin = DEM grid centre (UTM 8N); no vertical exaggeration. In three.js rotate tiles.group by -PI/2 about X to get the scene frame (x east, y up, z south).',
      centreUtm: [centreE, centreN],
      imagery: 'Sentinel-2 L2A TCI S2B_8VML_20240806_0_L2A (2024-08-06), the same ground image on every year of the time slider',
    },
  },
  geometricError: root.geometricError * 2,
  root,
};
writeFileSync(join(OUT, 'tileset.json'), JSON.stringify(tileset));
const meta = {
  tiles: tileCount,
  levels: LEVELS,
  cellsPerTile: [CX, CY],
  leafSpacingM: [+((EAST - WEST) / 2 ** (LEVELS - 1) / CX).toFixed(2), +((NORTH - SOUTH) / 2 ** (LEVELS - 1) / CY).toFixed(2)],
  maxTrianglesPerTile: maxTris,
  totalGlbBytes: glbBytes,
  meanTileBytes: Math.round(glbBytes / tileCount),
  largestTileBytes: largest,
  tilesetJsonBytes: statSync(join(OUT, 'tileset.json')).size,
  rootGeometricErrorM: root.geometricError,
  extentM: { west: WEST, east: EAST, south: SOUTH, north: NORTH },
  seconds: (Date.now() - t0) / 1000,
};
writeFileSync(join(OUT, 'build-meta.json'), JSON.stringify(meta, null, 1) + '\n');
console.log(meta);
